using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "DiceSecondActionLogic_RandomEnemyTarget", menuName = "Data/Battle/Logics/Dice Action/Dice Second Action Logic/DiceSecondActionLogic_RandomEnemyTarget")]
public class DiceSecondActionLogic_RandomEnemyTarget : DiceSecondActionLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	public override void OnDrop(ActionFace actionFace, GameObject target, GameObject source)
	{
		GameObject gameObject = null;
		gameObject = currentCorruptedAnimals.activeCorruptedAnimals.PickRandom();
		actionFace.SecondBattleAction.CastTargetAmount(gameObject, actionFace.SecondModifiedActionValue, source);
	}
}
